import React from 'react';
import BottomNav from './BottomNav';

export default function AppLayout({ children, noPadding }) {
  return (
    <div style={{
      minHeight: '100vh',
      background: '#111111',
      paddingBottom: noPadding ? 0 : 72,
      maxWidth: 430,
      margin: '0 auto',
      position: 'relative',
    }}>
      {children}
      <BottomNav />
    </div>
  );
}
